<script setup lang="ts">
import type { DocumentProvenance } from "../types/document-engine";
defineProps<{ conflict: DocumentProvenance | null; resolving: boolean; error: string; decision: string; justification: string }>();
const emit = defineEmits<{ close: []; resolve: []; "update:decision": [value: string]; "update:justification": [value: string] }>();
</script>

<template>
  <div v-if="conflict" class="fixed inset-0 z-20 grid place-items-center bg-[#123047]/40 p-4" @click.self="emit('close')"><form class="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="emit('resolve')"><div class="flex items-start justify-between"><div><p class="text-xs font-semibold uppercase tracking-wide text-[#159c9a]">Resolución autorizada</p><h3 class="mt-2 text-xl font-bold text-[#17313b]">{{ conflict.fieldPath }}</h3></div><button type="button" class="focus-ring text-2xl text-[#789098]" @click="emit('close')">×</button></div><p class="mt-4 rounded-xl bg-[#fffaf0] p-3 text-xs leading-5 text-[#856800]">La resolución registra una decisión y justificación sobre la proveniencia. No modifica revisiones anteriores.</p><label class="mt-5 block text-sm font-semibold text-[#49636b]">Decisión<select :value="decision" class="focus-ring mt-2 w-full rounded-lg border border-[#cbdce2] px-3 py-3 text-sm font-normal" @change="$emit('update:decision', ($event.target as HTMLSelectElement).value)"><option value="">Selecciona una decisión</option><option value="SOURCE_DOCUMENT">Priorizar documento fuente</option><option value="DONOR_RECORD">Priorizar registro canónico</option><option value="MANUAL">Resolver manualmente</option></select></label><label class="mt-4 block text-sm font-semibold text-[#49636b]">Justificación<textarea :value="justification" class="focus-ring mt-2 min-h-24 w-full rounded-xl border border-[#cbdce2] p-3 text-sm font-normal" @input="$emit('update:justification', ($event.target as HTMLTextAreaElement).value)" /></label><p v-if="error" class="mt-4 rounded-xl bg-[#fff0ef] p-3 text-xs text-[#ad4039]">{{ error }}</p><div class="mt-6 flex justify-end gap-3"><button type="button" class="focus-ring rounded-lg px-4 py-2 text-sm text-[#49636b]" @click="emit('close')">Cancelar</button><button class="focus-ring rounded-lg bg-[#123047] px-4 py-3 text-sm font-semibold text-white disabled:opacity-50" :disabled="resolving">{{ resolving ? "Resolviendo…" : "Registrar resolución" }}</button></div></form></div>
</template>
